tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_inbound_finds",
    "description": "Die Ernte-Funde: issueNumber, kategorie (F1=Edit an gemapptem Issue [pbiId gesetzt], F2=Neu-Issue, F7=Edit an bereits adoptiertem Issue [adoptedItemId gesetzt]), titel, details (deterministischer Diff), statement/akzeptanzkriterien/freitext aus dem geparsten Body.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "save_inbound_drafts",
    "description": "Speichert je Fund GENAU EINEN Draft: issueNumber, disposition (requirement|architecture|open_question|noise), draftText (die praezise deutsche Aussage fuer die Wahrheit; bei noise leer erlaubt), rationale. Genau einmal aufrufen.",
    "parameters": {
      "type": "object",
      "properties": {
        "drafts": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "issueNumber": {
                "type": "integer"
              },
              "disposition": {
                "type": "string"
              },
              "draftText": {
                "type": "string"
              },
              "rationale": {
                "type": "string"
              },
              "commentAnchor": {
                "type": [
                  "integer",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "issueNumber",
              "disposition",
              "draftText",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "drafts"
      ]
    }
  }
]

